for _ in range(int(input())):
	N = int(input())
	A = list(map(int, input().split()))
	if N == 1:
		print(1)
	elif N == 2:
		print(3)
	else:
		C = 2
		F = A[1] > A[0]
		final = 0
		for i in range(2, N):
			if not F or (F and A[i] > A[i - 1]):
				if not F and A[i] > A[i - 1]:
					F = True
				C += 1
			else:
				final += C * (C + 1) // 2
				if final > C * (C + 1) // 2:
					final -= 1
				C = 2
				F ^= True
		if C > 0:
			final += C * (C + 1) // 2
			if final > C * (C + 1) // 2:
				final -= 1
		print(final)
